// Абстрактный класс — и тип, и токен DI: TS-интерфейсы исчезают при компиляции
export abstract class ClusterSource {
  abstract pods(signal: AbortSignal): Promise<Pod[]>;
  abstract nodes(signal: AbortSignal): Promise<Node[]>;
  // … certificates, postgresCluster, backups, argoApps
}

export abstract class StateStore {
  /** null — состояния ещё нет: первый запуск */
  abstract load(signal: AbortSignal): Promise<State | null>;
  abstract save(state: State, signal: AbortSignal): Promise<void>;
}

export abstract class Notifier {
  abstract send(text: string, signal: AbortSignal): Promise<void>;
}

// Prober, AlertsSource, DiskStat — так же; часы — CLOCK из nest-common

// watchdogConfig = registerAs("watchdog", () => ({ dryRun: env().DRY_RUN, … }))
@Module({
  imports: [WatchdogConfigModule, ClockModule],
  providers: [
    RunnerService,
    { provide: ClusterSource, useClass: KubeClusterSource },
    { provide: Prober, useClass: FetchProber },
    { provide: AlertsSource, useClass: PrometheusAlerts },
    { provide: DiskStat, useClass: StatfsDisk },
    { provide: StateStore, useClass: ConfigMapStateStore },
    {
      provide: Notifier,
      inject: [watchdogConfig.KEY],
      useFactory: (cfg: ConfigType<typeof watchdogConfig>) =>
        cfg.dryRun
          ? new ConsoleNotifier()
          : new TelegramNotifier(cfg.telegramBotToken, cfg.telegramChatId),
    },
  ],
})
export class WatchdogModule {}

@Injectable()
export class RunnerService {
  constructor(
    private readonly cluster: ClusterSource,
    private readonly store: StateStore,
    private readonly notifier: Notifier,
    @Inject(CLOCK) private readonly clock: Clock,
    @Inject(watchdogConfig.KEY) private readonly cfg: ConfigType<typeof watchdogConfig>,
    // … Prober, AlertsSource, DiskStat
  ) {}

  async run(signal: AbortSignal): Promise<void> {
    const now = this.clock.now();
    const previous = await this.store.load(signal); // null — первый запуск
    const sources = await Promise.allSettled([
      this.cluster.pods(signal),
      this.cluster.nodes(signal),
      // … ещё семь источников
    ]);
    const findings = evaluate(sources, now); // чистые проверки: данные → находки
    const plan = planAlerts(previous, findings, now); // что отправить

    const delivered: boolean[] = [];
    for (const message of plan.messages) {
      try {
        await this.notifier.send(message.text, signal);
        delivered.push(true);
      } catch {
        delivered.push(false); // повторит следующий проход
      }
    }
    if (!this.cfg.dryRun) {
      await this.store.save(applyDelivery(plan, delivered), AbortSignal.timeout(10_000));
    }
  }
}

const app = await NestFactory.createApplicationContext(WatchdogModule, {
  logger: ["error", "warn"],
});
try {
  const cfg = app.get<ConfigType<typeof watchdogConfig>>(watchdogConfig.KEY);
  await app.get(RunnerService).run(AbortSignal.timeout(cfg.runTimeoutMs));
} catch (error) {
  console.error("pass failed", error);
  process.exitCode = 1;
} finally {
  await app.close();
}

