export abstract class Notifier {
  abstract send(text: string, signal: AbortSignal): Promise<void>;
}

// Адаптер для DRY_RUN
@Injectable()
export class ConsoleNotifier extends Notifier {
  async send(text: string): Promise<void> {
    console.log(`----- dry run: telegram message -----\n${text}`);
  }
}

// Фейк для теста: запоминает сообщения в памяти
export class RecordingNotifier extends Notifier {
  readonly sent: string[] = [];
  async send(text: string): Promise<void> {
    this.sent.push(text);
  }
}

// В тесте тот же модуль, но за токеном Notifier стоит фейк
const notifier = new RecordingNotifier();
const moduleRef = await Test.createTestingModule({ imports: [WatchdogModule] })
  .overrideProvider(Notifier)
  .useValue(notifier)
  .compile();

