// parseProbe splits "name=URL" like config.Probe.UnmarshalText,
// but reports a bad entry with false instead of an error.
func parseProbe(entry string) (name, target string, ok bool) {
	name, target, ok = strings.Cut(strings.TrimSpace(entry), "=")
	name, target = strings.TrimSpace(name), strings.TrimSpace(target)
	return name, target, ok && name != "" && target != ""
}

func findingKey(parts ...string) string {
	return strings.Join(parts, ":")
}

