	if err != nil {
		fmt.Printf("statfs(%d, %d, %d): error: %v (pct = %d)\n", blocks, free, avail, err, pct)
		return
	}
	fmt.Printf("statfs(%d, %d, %d): %d%% used\n", blocks, free, avail, pct)
