// fetch ждёт ответа не дольше, чем живёт ctx.
func fetch(ctx context.Context, buffer int) error {
	answer := make(chan string, buffer)
	go func() {
		time.Sleep(100 * time.Millisecond) // медленный источник
		answer <- "ok"                     // без буфера ждёт читателя вечно
	}()
	select {
	case <-answer:
		return nil
	case <-ctx.Done():
		return ctx.Err()
	}
}

func main() {
	for _, buffer := range []int{0, 1} {
		before := runtime.NumGoroutine()
		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Millisecond)
		err := fetch(ctx, buffer)
		cancel()
		time.Sleep(300 * time.Millisecond) // горутине хватит времени закончить
		fmt.Printf("буфер %d: %v; осталось горутин: %d\n", buffer, err, runtime.NumGoroutine()-before)
	}
}

