		return errors.New("disk: permission denied")
	})

	start := time.Now()
	err := g.Wait()
	slices.Sort(lines) // горутины заканчивают в любом порядке
	for _, line := range lines {
		fmt.Println(line)
	}
	fmt.Println("Wait вернул:", err)
