type memStore struct {
	mu      sync.Mutex
	state   *domain.State
	loadErr error
	saveErr error
	saves   int
}

// … Load отдаёт копию сохранённого состояния или loadErr

func (s *memStore) Save(_ context.Context, st domain.State) error {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.saves++
	if s.saveErr != nil {
		return s.saveErr
	}
	// … запоминает копию st в s.state
	return nil
}

type recorder struct {
	mu   sync.Mutex
	sent []string
	fail bool
}

func (r *recorder) Send(_ context.Context, text string) error {
	r.mu.Lock()
	defer r.mu.Unlock()
	if r.fail {
		return errors.New("telegram is down")
	}
	r.sent = append(r.sent, text)
	return nil
}

