/// What the watchdog remembers about the previous passes.
#[derive(Debug, Clone, Default, PartialEq, Eq)]
pub struct State {
    /// Known problems by finding key. A `BTreeMap` keeps keys sorted, which
    /// gives deterministic message lines and a stable JSON diff.
    pub findings: BTreeMap<String, Entry>,
    /// `YYYYMMDD` (UTC) of the last delivered daily digest.
    pub digest_day: Option<String>,
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct Entry {
    /// Unix seconds when the problem was first seen.
    pub since: i64,
    /// Unix seconds of the last delivered alert or reminder; `0` = never.
    pub notified: i64,
    /// The last message of this finding (used for "recovered").
    pub message: String,
}

/// Decides what to send. `previous` is `None` on the first run.
pub fn plan(
    previous: Option<&State>,
    findings: &[Finding],
    facts: &Facts,
    now: DateTime<Utc>,
) -> Plan {
    let ts = now.timestamp();
    let empty = State::default();
    let prev = previous.unwrap_or(&empty);

    // First finding per key wins; iteration is in key order.
    let mut current: BTreeMap<&str, &Finding> = BTreeMap::new();
    for finding in findings {
        current.entry(finding.key.as_str()).or_insert(finding);
    }

    let mut next = State {
        findings: BTreeMap::new(),
        digest_day: prev.digest_day.clone(),
    };
    let mut problems = Vec::new();
    let mut reminders = Vec::new();
    for (&key, finding) in &current {
        let (since, notified) = prev
            .findings
            .get(key)
            .map_or((ts, 0), |entry| (entry.since, entry.notified));
        if ts - since >= grace_secs(key) {
            if notified == 0 {
                problems.push(*finding);
            } else if ts - notified >= REMIND_AFTER_SECS {
                reminders.push(*finding);
            }
        }
        next.findings.insert(
            key.to_owned(),
            Entry {
                since,
                notified,
                message: finding.message.clone(),
            },
        );
    }

    // … восстановления, приветствие, сводка и сборка Plan
}

// Внутреннее замыкание без move заимствует prefix — локальную переменную внешнего замыкания.
struct Node {
    name: String,
    conditions: Vec<String>,
}

fn problems(nodes: &[Node]) -> Vec<String> {
    nodes
        .iter()
        .flat_map(|node| {
            let prefix = format!("node:{}", node.name);
            node.conditions.iter().map(|c| format!("{prefix}:{c}"))
        })
        .collect()
}

fn main() {
    let nodes = vec![Node {
        name: "srv1".to_owned(),
        conditions: vec!["DiskPressure".to_owned()],
    }];
    println!("{:?}", problems(&nodes));
}

/// `Ready` not `True`, or any other condition `True` (memory, disk or PID
/// pressure, network unavailable).
pub fn evaluate(nodes: &[Node]) -> Vec<Finding> {
    nodes
        .iter()
        .flat_map(|node| {
            node.conditions
                .iter()
                .filter(|c| is_problem(c))
                .map(move |c| {
                    Finding::new(
                        format!("node:{}:{}", node.name, c.kind),
                        format!(
                            "node {}: {}={} ({})",
                            node.name,
                            c.kind,
                            c.status,
                            c.reason.as_deref().unwrap_or_default()
                        ),
                    )
                })
        })
        .collect()
}

fn is_problem(condition: &Condition) -> bool {
    if condition.kind == "Ready" {
        !condition.is_true()
    } else {
        condition.is_true()
    }
}

export function checkPods(pods: Pod[], watched: string[], now: Date): Finding[] {
  return pods
    .filter((p) => watched.includes(p.namespace))
    .filter((p) => p.phase !== 'Succeeded')
    .filter((p) => !p.ownerKinds.includes('Job'))
    .flatMap((p) => {
      const finding = problem(p, now);
      return finding ? [finding] : [];
    });
}

fn is_watched(pod: &Pod, watched: &[String]) -> bool {
    watched.contains(&pod.namespace)
}

fn is_job_pod(pod: &Pod) -> bool {
    pod.owner_kinds.iter().any(|kind| kind == "Job")
}

/// Crash loops, image pull errors and pods not ready for over 10 minutes in
/// watched namespaces. Completed pods and pods of Jobs are ignored.
pub fn evaluate(pods: &[Pod], watched: &[String], now: DateTime<Utc>) -> Vec<Finding> {
    pods.iter()
        .filter(|pod| is_watched(pod, watched))
        .filter(|pod| pod.phase.as_deref() != Some("Succeeded"))
        .filter(|pod| !is_job_pod(pod))
        .filter_map(|pod| problem(pod, now))
        .collect()
}

