/// What the backup check found: maybe a finding, and the age for the digest.
#[derive(Debug, PartialEq, Eq)]
pub struct BackupStatus {
    pub finding: Option<Finding>,
    pub age_hours: Option<i64>,
}

/// Looks at the newest `completed` backup by `stoppedAt`.
pub fn backups(backups: &[Backup], now: DateTime<Utc>) -> BackupStatus {
    let last = backups
        .iter()
        .filter(|b| b.phase.as_deref() == Some("completed"))
        .filter_map(|b| b.stopped_at)
        .max();
    match last {
        None => BackupStatus {
            finding: Some(Finding::new("pg:backup-age", "no completed backup found")),
            age_hours: None,
        },
        Some(stopped) => {
            // Integer division truncates like the script's `$(( ... / 3600 ))`.
            let hours = (now - stopped).num_seconds() / 3600;
            BackupStatus {
                finding: (hours >= BACKUP_MAX_AGE_HOURS).then(|| {
                    Finding::new(
                        "pg:backup-age",
                        format!("last completed backup is {hours} h old"),
                    )
                }),
                age_hours: Some(hours),
            }
        }
    }
}

/// The smallest number of days left among certificates that know `notAfter`.
pub fn min_days_left(certs: &[Certificate], now: DateTime<Utc>) -> Option<i64> {
    certs
        .iter()
        .filter_map(|cert| cert.not_after)
        .map(|not_after| days_left(not_after, now))
        .min()
}

fn problem(pod: &Pod, now: DateTime<Utc>) -> Option<Finding> {
    let key = format!("pod:{}/{}", pod.namespace, app_name(pod));
    let bad_reason = pod
        .containers
        .iter()
        .filter_map(|c| c.waiting_reason.as_deref())
        .find(|reason| BAD_WAITING_REASONS.contains(reason));
    if let Some(reason) = bad_reason {
        return Some(Finding::new(
            key,
            format!("{}/{}: {reason}", pod.namespace, pod.name),
        ));
    }

    // … дальше — цепочка Option из раздела выше
}

/// Keeps the first finding for each key and sorts by key.
///
/// The sort is stable, so among equal keys the original order survives and
/// `dedup_by` keeps the earliest one. No key is cloned.
pub fn dedup(mut findings: Vec<Finding>) -> Vec<Finding> {
    findings.sort_by(|a, b| a.key.cmp(&b.key));
    findings.dedup_by(|later, earlier| later.key == earlier.key);
    findings
}

/// Unique non-empty values of [`SCOPE_LABELS`], sorted, joined with `/`
/// (`jq 'map(select(. != null)) | unique | join("/")'`).
pub fn scope(labels: &BTreeMap<String, String>) -> String {
    SCOPE_LABELS
        .iter()
        .filter_map(|label| non_empty(labels.get(*label)))
        .collect::<BTreeSet<_>>()
        .into_iter()
        .collect::<Vec<_>>()
        .join("/")
}

