import { z } from 'zod';

const entrySchema = z.object({
  since: z.number().int(),
  notified: z.number().int(),
  message: z.string(),
});

const stateSchema = z.object({
  version: z.literal(1),
  digestDay: z.string().optional(),
  entries: z.record(z.string(), entrySchema).default({}),
});

export type StateDocument = z.infer<typeof stateSchema>;

export const decodeState = (json: string): StateDocument =>
  stateSchema.parse(JSON.parse(json));

// State is what the watchdog remembers between passes.
type State struct {
	// Version is always StateVersion when encoded.
	Version int `json:"version"`
	// DigestDay is the UTC day (YYYYMMDD) of the last delivered daily digest.
	DigestDay string `json:"digestDay,omitempty"`
	// Entries maps a finding key to what is known about that problem.
	Entries map[string]Entry `json:"entries"`
}

// Entry tracks one problem. Times are unix seconds; Notified == 0 means the
// owner has not been told yet.
type Entry struct {
	Since    int64  `json:"since"`
	Notified int64  `json:"notified"`
	Message  string `json:"message"`
}

/// Current format version; anything else is treated as unreadable.
pub const STATE_VERSION: u32 = 1;

// …

/// The on-disk shape. Kept separate from [`State`] so the format can evolve
/// (a `version` field, camelCase names) without leaking into the core.
#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct DocumentRef<'a> {
    version: u32,
    #[serde(skip_serializing_if = "Option::is_none")]
    digest_day: Option<&'a str>,
    #[serde(rename = "entries")]
    findings: &'a BTreeMap<String, Entry>,
}

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct Document {
    #[serde(default)]
    digest_day: Option<String>,
    #[serde(default, rename = "entries")]
    findings: BTreeMap<String, Entry>,
}

#[derive(Deserialize)]
struct Versioned {
    version: u32,
}

// …

/// Serializes the state as pretty JSON (readable in `kubectl get cm -o yaml`).
pub fn encode(state: &State) -> Result<String, serde_json::Error> {
    serde_json::to_string_pretty(&DocumentRef {
        version: STATE_VERSION,
        digest_day: state.digest_day.as_deref(),
        findings: &state.findings,
    })
}

/// Parses `state.json`, rejecting other versions before looking at the body.
// Упрощено: в настоящем коде ошибка — перечисление DecodeError (глава 12).
pub fn decode(json: &str) -> Result<State, String> {
    let Versioned { version } = serde_json::from_str(json).map_err(|err| err.to_string())?;
    if version != STATE_VERSION {
        return Err(format!("unsupported state version {version}"));
    }
    let doc: Document = serde_json::from_str(json).map_err(|err| err.to_string())?;
    Ok(State {
        findings: doc.findings,
        digest_day: doc.digest_day,
    })
}

// … State, Entry, DocumentRef, Document, Versioned, encode и decode — как в листинге выше

fn main() {
    let mut state = State::default();
    state.findings.insert(
        "disk".to_owned(),
        Entry {
            since: 100,
            notified: 0,
            message: "server disk 91% used".to_owned(),
        },
    );
    let json = encode(&state).unwrap_or_default();
    println!("{json}");
    println!("round trip: {}", decode(&json) == Ok(state));

    // Так пишет состояние Go-версия (go/internal/domain/state.go).
    let from_go = r#"{"version":1,"digestDay":"20261010","entries":{"disk":{"since":100,"notified":200,"message":"server disk 85% used"}}}"#;
    match decode(from_go) {
        Ok(state) => println!("{:?} {}", state.digest_day, state.findings["disk"].notified),
        Err(err) => println!("error: {err}"),
    }
    println!("{:?}", decode(r#"{"version":2,"entries":{}}"#));
    println!("{:?}", decode(r#"{"entries":{}}"#));
}

