    clock.now().hour() >= 7
}

fn main() {
    // 2026-10-10 07:00:00 UTC
    let morning = FixedClock(DateTime::UNIX_EPOCH + TimeDelta::seconds(1_791_615_600));
    let early = FixedClock(morning.now() - TimeDelta::hours(5));

    println!("{} digest: {}", morning.today(), digest_due(&morning));
    println!("{} digest: {}", early.today(), digest_due(&early));
    println!(
        "system clock is later: {}",
        SystemClock.now() > morning.now()
    );
}

