impl fmt::Display for PercentError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            PercentError::Parse(_) => f.write_str("cannot parse percent"),
            PercentError::OutOfRange(value) => write!(f, "{value}% is more than 100%"),
        }
    }
}

impl Error for PercentError {
    fn source(&self) -> Option<&(dyn Error + 'static)> {
        match self {
            PercentError::Parse(err) => Some(err),
            PercentError::OutOfRange(_) => None,
        }
    }
}

/// What `?` calls when a `ParseIntError` meets a function returning `PercentError`.
impl From<ParseIntError> for PercentError {
    fn from(err: ParseIntError) -> Self {
        PercentError::Parse(err)
    }
}

