package main

import (
	"fmt"
	"strconv"
	"strings"
)

func parsePercent(text string) (uint8, error) {
	value, err := strconv.ParseUint(strings.TrimSpace(text), 10, 8)
	if err != nil {
		return 0, fmt.Errorf("cannot parse percent: %w", err)
	}
	if value > 100 {
		return 0, fmt.Errorf("%d%% is more than 100%%", value)
	}
	return uint8(value), nil
}

