    /// Clones the data so no lock is held across `.await`.
    async fn answer<T: Clone>(
        &self,
        pick: impl Fn(&ClusterData) -> Option<T>,
    ) -> Result<T, SourceError> {
        let (value, delay) = {
            let data = self.data.lock().unwrap();
            (pick(&data), data.delay)
        };
