private async collect(now: Date, signal: AbortSignal): Promise<Collected> {
  // дедлайн проверок = 3/4 прохода, плюс внешняя отмена (сигнал)
  const checks = AbortSignal.any([signal, AbortSignal.timeout(this.cfg.checksTimeoutMs)]);
  const ns = this.cfg.namespace;
  const [pods, nodes, disk, certs, pg, backups, argo, probes, alerts] = await Promise.allSettled([
    this.cluster.pods(checks),
    this.cluster.nodes(checks),
    this.disk.usedPercent(),
    this.cluster.certificates(checks),
    this.cluster.postgresCluster(ns, 'pg', checks),
    this.cluster.backups(ns, checks),
    this.cluster.argoApps('argocd', checks),
    this.probeAll(checks),
    this.alerts.alerts(checks),
  ]);
  if (signal.aborted) throw new PassInterruptedError({ cause: signal.reason });
  // … fulfilled → проверка, rejected → находка или предупреждение в логе
}

