use std::time::Duration;

use tokio::time::{Instant, sleep, sleep_until};

#[derive(Debug)]
enum SourceError {
    Deadline,
}

/// Тот же bounded, что в run.rs, но через select!.
async fn bounded<T>(
    deadline: Instant,
    source: impl Future<Output = Result<T, SourceError>>,
) -> Result<T, SourceError> {
    tokio::select! {
        result = source => result,
        () = sleep_until(deadline) => Err(SourceError::Deadline),
    }
}

async fn fast() -> Result<u16, SourceError> {
    sleep(Duration::from_millis(1)).await;
    Ok(204)
}

async fn slow() -> Result<u16, SourceError> {
    sleep(Duration::from_secs(5)).await;
    Ok(200)
}

#[tokio::main(flavor = "current_thread")]
async fn main() {
    let deadline = Instant::now() + Duration::from_millis(50);
    println!("fast: {:?}", bounded(deadline, fast()).await);
    println!("slow: {:?}", bounded(deadline, slow()).await);
}

