async function bootstrap(): Promise<number> {
  const app = await NestFactory.createApplicationContext(WatchdogModule, { bufferLogs: true });
  const shutdown = new AbortController();
  for (const sig of ['SIGTERM', 'SIGINT'] as const) {
    process.once(sig, () => shutdown.abort(new Error(sig)));
  }
  const cfg = app.get(ConfigService<Env, true>);
  const pass = AbortSignal.any([
    shutdown.signal,
    AbortSignal.timeout(cfg.get('RUN_TIMEOUT_MS', { infer: true })),
  ]);
  try {
    await app.get(RunnerService).run(pass);
    return 0;
  } catch (err) {
    app.get(Logger).error({ err }, 'pass failed');
    return shutdown.signal.aborted ? 143 : 1;
  } finally {
    await app.close();
  }
}

void bootstrap().then((code) => {
  process.exitCode = code;
});

