@Injectable()
export class RunnerService {
  private readonly logger = new Logger(RunnerService.name);

  constructor(
    private readonly store: StateStore,
    private readonly notifier: Notifier,
    @Inject(CLOCK) private readonly clock: Clock,
    private readonly config: ConfigService<Env, true>,
    // … ClusterSource, Prober, AlertsSource, DiskStat — для collect
  ) {}

  async run(signal: AbortSignal): Promise<void> {
    const now = this.clock.now();
    const previous = await this.store.load(signal); // 3. null — первый запуск
    const collected = await this.collect(now, signal); // 3. Promise.allSettled по девяти источникам
    const findings = dedupe(collected.findings); // 4. первая находка с ключом побеждает
    const plan = planAlerts(previous, findings, collected.facts, now); // 5. что сказать

    const delivered: boolean[] = [];
    for (const message of plan.messages) { // 6. по одному сообщению
      try {
        await this.notifier.send(message.text, signal);
        delivered.push(true);
      } catch {
        this.logger.error(`message not delivered: ${message.kind}`);
        delivered.push(false); // повторит следующий проход
      }
    }
    const next = applyDelivery(plan, delivered); // 7. запомнить только доставленное
    if (!this.config.get('DRY_RUN', { infer: true })) {
      await this.store.save(next, AbortSignal.timeout(10_000)); // 8. своя отмена, не signal
    }
    if (signal.aborted) throw new PassInterruptedError({ cause: signal.reason });
  }

  // … collect из главы 6
}

