async fn run(config: Config) -> anyhow::Result<ExitCode> {
    // Handlers first: from here on a signal cancels the pass cleanly instead
    // of killing the process with the default action.
    let mut terminate = signal(SignalKind::terminate()).context("cannot handle SIGTERM")?;
    let mut interrupt = signal(SignalKind::interrupt()).context("cannot handle SIGINT")?;

    let kube = cluster::client()
        .await
        .context("cannot create Kubernetes client")?;
    let http = adapters::http::client().context("cannot create HTTP client")?;
    // … PrometheusAlerts::new

    // Constructor injection: every port gets its adapter here and nowhere else.
    let deps = Deps {
        cluster: Arc::new(KubeCluster::new(kube.clone())),
        // … prober, alerts, disk, store
        notifier: adapters::notifier_for(&config.delivery, http),
        clock: Arc::new(SystemClock),
    };
    let settings = Settings::from(&config);

    // Whichever finishes first wins; the losing future is dropped, which
    // cancels in-flight requests and aborts the probe tasks.
    tokio::select! {
        result = run::run_once(&deps, &settings) => {
            result?;
            Ok(ExitCode::SUCCESS)
        }
        _ = terminate.recv() => Ok(cancelled("SIGTERM", 15)),
        _ = interrupt.recv() => Ok(cancelled("SIGINT", 2)),
    }
}

func (r *Runner) Run(ctx context.Context) (Summary, error) {
	// … start, sum и done — для итоговой строки
	now := r.deps.Clock.Now()

	stored, found, err := r.deps.Store.Load(ctx)
	if errors.Is(err, ports.ErrCorruptState) {
		r.log.WarnContext(ctx, "stored state is unreadable, treating this pass as the first run", "error", err)
		found, err = false, nil
	}
	if err != nil {
		return done(fmt.Errorf("load state: %w", err))
	}
	var prev *domain.State
	if found {
		prev = &stored
	}
	sum.FirstRun = prev == nil

	res, err := r.collect(ctx, now)
	if err != nil {
		return done(err)
	}

pub async fn run_once(deps: &Deps, settings: &Settings) -> Result<Summary, RunError> {
    let started = Instant::now();
    let deadline = started + settings.run_timeout;
    let now = deps.clock.now();

    let load_state = async {
        timeout_at(deadline, deps.store.load())
            .await
            .unwrap_or_else(|elapsed| Err(StoreError::Read(Box::new(elapsed))))
    };
    let (previous, observations) = tokio::join!(load_state, gather(deps, settings, deadline));
    let previous = previous.map_err(RunError::Load)?;
    if previous.is_none() {
        info!("no previous state: first run");
    }
    log_unavailable(&observations);
    // …

