use std::time::Duration;

use tokio::time::{Instant, sleep, sleep_until};

/// Отправка одного сообщения: 100 мс, как будто ходим в Telegram.
async fn send(text: &str) {
    sleep(Duration::from_millis(100)).await;
    println!("доставлено: {text}");
}

#[tokio::main(flavor = "current_thread")]
async fn main() {
    // Вместо SIGTERM — момент времени: сигнал «придёт» через 150 мс,
    // посреди второй отправки.
    let signal_at = Instant::now() + Duration::from_millis(150);
    let messages = ["🔴 problem", "🟠 still failing", "☀️ daily"];

    let mut delivered = Vec::new();
    let mut interrupted = false;
    for text in messages {
        // Сигнал отменяет только текущую отправку, а не весь проход.
        tokio::select! {
            () = send(text) => delivered.push(text),
            () = sleep_until(signal_at) => {
                println!("сигнал: отправка «{text}» прервана");
                interrupted = true;
                break;
            }
        }
    }

    // Запись идёт после select!: сигнал её уже не отменит.
    println!("сохраняем состояние: доставлено {delivered:?}");
    if interrupted {
        println!("код выхода 1: проход прерван");
    } else {
        println!("код выхода 0");
    }
}
